def transform(grid):
    h, w = len(grid), len(grid[0])
    seed = next(((r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == 3), None)
    if seed is None:
        return [row[:] for row in grid]

    # The motif is a set of nested, interrupted rectangular tracks.
    offsets = {
        -4: (-4, -2, -1, 0, 1, 2, 3, 4),
        -3: (-4, -2, 4),
        -2: (-4, -2, 0, 1, 2, 4),
        -1: (-4, -2, 0, 2, 4),
         0: (-4, -2, 0, 2, 4),
         1: (-4, -2, 2, 4),
         2: (-4, -2, -1, 0, 1, 2, 4),
         3: (-4, 4),
         4: tuple(range(-4, 5)),
    }
    sr, sc = seed
    motif = set()
    for dr, dcs in offsets.items():
        for dc in dcs:
            r, c = sr + dr, sc + dc
            if 0 <= r < h and 0 <= c < w:
                motif.add((r, c))

    # Keep the part of the track connected to the seed; 2s interrupt tracks.
    reached = {seed}
    stack = [seed]
    while stack:
        r, c = stack.pop()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if ((nr, nc) in motif and (nr, nc) not in reached
                    and grid[nr][nc] != 2):
                reached.add((nr, nc))
                stack.append((nr, nc))

    out = [row[:] for row in grid]
    for r, c in reached:
        if out[r][c] == 0:
            out[r][c] = 3
    return out
